export function geography() {
  if (groups.length !== 20) throw Error("Geografia: completar vinte situações");
  return Array.from({ length: 5 }, (_, variant) => groups.map((g, index) => ({ ...g[variant], family: `G${index + 1}`, variant: variant + 1 }))).flat();
}
